import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] h = {1, 3, 2, 7, 4, 5};          // a min-heap written level by level
        int n = h.length;
        System.out.println("heap array: " + Arrays.toString(h));
        boolean ok = true;
        for (int i = 0; i < n; i++) {
            // Index arithmetic replaces pointers: parent (i-1)/2, children 2i+1 and 2i+2.
            int p = (i - 1) / 2, l = 2 * i + 1, r = 2 * i + 2;
            String ps = i == 0 ? "-" : String.valueOf(h[p]);
            String ls = l < n ? String.valueOf(h[l]) : "-";   // "-" means no such node
            String rs = r < n ? String.valueOf(h[r]) : "-";
            System.out.println("i=" + i + " value=" + h[i] + " parent=" + ps + " left=" + ls + " right=" + rs);
            if (i > 0 && h[p] > h[i]) ok = false;             // heap order: parent <= child
        }
        System.out.println("min-heap order holds: " + (ok ? "yes" : "no"));
        // Time: O(N) to check every node. Space: O(1) extra.
    }
}

