import java.util.*;

public class Main {
    static List<Integer> h = new ArrayList<>();

    static void insert(int x) {
        h.add(x);                                   // 1. put it at the end (shape stays complete)
        int i = h.size() - 1;
        while (i > 0 && h.get(i) < h.get((i - 1) / 2)) {   // 2. sift up while smaller than the parent
            Collections.swap(h, i, (i - 1) / 2);
            i = (i - 1) / 2;
        }
    }

    static int extractMin() {
        int min = h.get(0);
        int last = h.remove(h.size() - 1);          // 1. take the last element out
        if (!h.isEmpty()) {
            h.set(0, last);                         // 2. move it to the root
            int i = 0, n = h.size();
            while (true) {                          // 3. sift down: swap with the SMALLER child
                int m = i, l = 2 * i + 1, r = l + 1;
                if (l < n && h.get(l) < h.get(m)) m = l;
                if (r < n && h.get(r) < h.get(m)) m = r;
                if (m == i) break;
                Collections.swap(h, i, m);
                i = m;
            }
        }
        return min;
    }

    public static void main(String[] args) {
        for (int x : new int[]{5, 3, 8, 1, 4}) {
            insert(x);
            System.out.println("insert " + x + " -> " + h);
        }
        for (int k = 0; k < 2; k++) {
            int m = extractMin();
            System.out.println("extract-min = " + m + " -> " + h);
        }
        // Time: O(log N) per insert or extract. Space: O(N) for the array.
    }
}

