public class Main {
    // Sift a[i] down inside a[0..n); return how many swaps it took.
    static long siftDown(int[] a, int i, int n) {
        long swaps = 0;
        while (true) {
            int m = i, l = 2 * i + 1, r = l + 1;
            if (l < n && a[l] < a[m]) m = l;
            if (r < n && a[r] < a[m]) m = r;
            if (m == i) return swaps;
            int t = a[i]; a[i] = a[m]; a[m] = t;
            i = m;
            swaps++;
        }
    }

    static long bottomUp(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = n - i;        // n, n-1, ..., 1: worst case for a min-heap
        long swaps = 0;
        for (int i = n / 2 - 1; i >= 0; i--) swaps += siftDown(a, i, n);   // last parent back to the root
        return swaps;
    }

    static long oneByOne(int n) {
        int[] a = new int[n];
        long swaps = 0;
        for (int k = 0; k < n; k++) {                    // insert at the end, then sift up
            a[k] = n - k;
            int i = k;
            while (i > 0 && a[i] < a[(i - 1) / 2]) {
                int p = (i - 1) / 2;
                int t = a[i]; a[i] = a[p]; a[p] = t;
                i = p;
                swaps++;
            }
        }
        return swaps;
    }

    public static void main(String[] args) {
        System.out.println("input: n, n-1, ..., 1 (descending)");
        for (int n : new int[]{15, 1023, 65535}) {
            System.out.println("n=" + n + " bottom-up swaps=" + bottomUp(n) + " one-by-one swaps=" + oneByOne(n));
        }
        // Bottom-up: O(N) time (swaps stay below N). One by one: O(N log N). Space: O(1) extra.
    }
}

