import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] nums = {3, 2, 1, 5, 6, 4};
        int k = 2;
        System.out.println("nums: " + Arrays.toString(nums) + ", k = " + k);

        PriorityQueue<Integer> heap = new PriorityQueue<>();   // min-heap
        for (int x : nums) {
            heap.add(x);
            // Keep only the k largest seen so far: throw away the smallest of k+1.
            if (heap.size() > k) heap.poll();
            System.out.println("after " + x + ": smallest kept = " + heap.peek() + ", size = " + heap.size());
        }
        // The smallest of the k largest values is the kth largest.
        System.out.println("kth largest: " + heap.peek());
        // Time: O(N log K). Space: O(K).
    }
}

