using System;
using System.Collections.Generic;

class Program {
    // Tiny binary min-heap of int[] keys, compared left to right.
    static bool Less(int[] a, int[] b) {
        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return a[i] < b[i];
        return false;
    }
    static void Push(List<int[]> h, int[] x) {
        h.Add(x);
        int i = h.Count - 1;
        while (i > 0 && Less(h[i], h[(i - 1) / 2])) {
            int p = (i - 1) / 2;
            int[] t = h[i]; h[i] = h[p]; h[p] = t;
            i = p;
        }
    }
    static int[] Pop(List<int[]> h) {
        int[] top = h[0];
        h[0] = h[h.Count - 1];
        h.RemoveAt(h.Count - 1);
        int i = 0;
        while (true) {
            int m = i, l = 2 * i + 1, r = l + 1;
            if (l < h.Count && Less(h[l], h[m])) m = l;
            if (r < h.Count && Less(h[r], h[m])) m = r;
            if (m == i) break;
            int[] t = h[i]; h[i] = h[m]; h[m] = t;
            i = m;
        }
        return top;
    }

    static void Main() {
        int[] nums = {3, 2, 1, 5, 6, 4};
        int k = 2;
        Console.WriteLine("nums: [" + string.Join(", ", nums) + "], k = " + k);

        List<int[]> heap = new List<int[]>();            // min-heap, each key is {value}
        foreach (int x in nums) {
            Push(heap, new int[] {x});
            // Keep only the k largest seen so far: throw away the smallest of k+1.
            if (heap.Count > k) Pop(heap);
            Console.WriteLine("after " + x + ": smallest kept = " + heap[0][0] + ", size = " + heap.Count);
        }
        // The smallest of the k largest values is the kth largest.
        Console.WriteLine("kth largest: " + heap[0][0]);
        // Time: O(N log K). Space: O(K).
    }
}

