using System;
using System.Collections.Generic;

class Program {
    // Tiny binary min-heap of int[] keys, compared left to right.
    static bool Less(int[] a, int[] b) {
        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return a[i] < b[i];
        return false;
    }
    static void Push(List<int[]> h, int[] x) {
        h.Add(x);
        int i = h.Count - 1;
        while (i > 0 && Less(h[i], h[(i - 1) / 2])) {
            int p = (i - 1) / 2;
            int[] t = h[i]; h[i] = h[p]; h[p] = t;
            i = p;
        }
    }
    static int[] Pop(List<int[]> h) {
        int[] top = h[0];
        h[0] = h[h.Count - 1];
        h.RemoveAt(h.Count - 1);
        int i = 0;
        while (true) {
            int m = i, l = 2 * i + 1, r = l + 1;
            if (l < h.Count && Less(h[l], h[m])) m = l;
            if (r < h.Count && Less(h[r], h[m])) m = r;
            if (m == i) break;
            int[] t = h[i]; h[i] = h[m]; h[m] = t;
            i = m;
        }
        return top;
    }

    static void Main() {
        int[] values = {5, 1, 8, 3};
        Console.WriteLine("values: [" + string.Join(", ", values) + "]");

        // The helper is a min-heap, so store the negated value to get a max-heap.
        List<int[]> maxHeap = new List<int[]>();
        foreach (int v in values) Push(maxHeap, new int[] {-v});
        string order = "";
        while (maxHeap.Count > 0) order += " " + (-Pop(maxHeap)[0]);   // pop, do not iterate
        Console.WriteLine("max-heap poll order:" + order);

        // Pitfall: the comparator (a, b) => b - a overflows for far-apart values.
        int a = -2000000000, b = 2000000000;
        int diff = unchecked(b - a);               // real answer 4,000,000,000 does not fit in 32 bits
        Console.WriteLine("a = " + a + ", b = " + b);
        Console.WriteLine("b - a as a 32-bit int: " + diff + " (negative, so the order is wrong)");
        Console.WriteLine("safe compare(b, a) sign: " + b.CompareTo(a));
        // Time: O(N log N) to push and pop N values. Space: O(N).
    }
}

