        heap.pop();
        merged.push_back(get<0>(top));
        int li = get<1>(top), pos = get<2>(top) + 1;
        if (pos < (int)lists[li].size()) heap.push(Entry(lists[li][pos], li, pos));   // push its successor
    }
    cout << "merged: " << show(merged) << "\n";
