import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] stream = {5, 15, 1, 3, 8};
        System.out.println("stream: " + Arrays.toString(stream));

        PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder());   // smaller half, max on top
        PriorityQueue<Integer> high = new PriorityQueue<>();                            // larger half, min on top
        for (int x : stream) {
            low.add(x);
            high.add(low.poll());                              // pass low's largest across, so low <= high
            if (high.size() > low.size()) low.add(high.poll());   // low keeps the extra element
            // Odd count: the middle is low's top. Even count: average of the two tops.
            double median = low.size() > high.size() ? low.peek() : (low.peek() + (long) high.peek()) / 2.0;
            System.out.println("add " + x + " -> median " + String.format(Locale.ROOT, "%.1f", median));
        }
        // Time: O(log N) per add, O(1) per median. Space: O(N).
    }
}

