public class Main {
    static int[][] next = new int[64][26];   // next[node][letter] = child node, 0 means "no child"
    static boolean[] isEnd = new boolean[64];
    static int size = 1;                      // node 0 is the root

    static void insert(String w) {
        int node = 0;
        for (char ch : w.toCharArray()) {
            int c = ch - 'a';
            if (next[node][c] == 0) next[node][c] = size++;   // create the missing child
            node = next[node][c];
        }
        isEnd[node] = true;                   // a word ends here
    }

    // Follow s from the root; return the node reached, or -1 if the path breaks.
    static int walk(String s) {
        int node = 0;
        for (char ch : s.toCharArray()) {
            node = next[node][ch - 'a'];
            if (node == 0) return -1;
        }
        return node;
    }

    static String yn(boolean b) { return b ? "yes" : "no"; }

    public static void main(String[] args) {
        String[] words = {"apple", "app", "bat"};
        for (String w : words) insert(w);
        System.out.println("words: " + String.join(", ", words));
        int n;
        n = walk("app"); System.out.println("search(app): " + yn(n != -1 && isEnd[n]));
        n = walk("ap");  System.out.println("search(ap): " + yn(n != -1 && isEnd[n]));   // a prefix, not a word
        System.out.println("startsWith(ap): " + yn(walk("ap") != -1));
        System.out.println("startsWith(bo): " + yn(walk("bo") != -1));
        System.out.println("nodes used: " + size);
        // Time: O(L) per operation for a word of length L. Space: O(total letters * 26).
    }
}

