    int node = 0;
    for (char ch : w) {
        int c = ch - 'a';
        if (nxt[node][c] == 0) nxt[node][c] = sz++;   // create the missing child
        node = nxt[node][c];
    }
    isEnd[node] = true;                               // a word ends here
}

// Follow s from the root; return the node reached, or -1 if the path breaks.
int walk(const string& s) {
    int node = 0;
    for (char ch : s) {
        node = nxt[node][ch - 'a'];
        if (node == 0) return -1;
    }
    return node;
}

