using System;

class Program {
    static int[,] next = new int[64, 26];    // next[node, letter] = child node, 0 means "no child"
    static bool[] isEnd = new bool[64];
    static int size = 1;                      // node 0 is the root

    static void Insert(string w) {
        int node = 0;
        foreach (char ch in w) {
            int c = ch - 'a';
            if (next[node, c] == 0) next[node, c] = size++;   // create the missing child
            node = next[node, c];
        }
        isEnd[node] = true;                   // a word ends here
    }

    // Follow s from the root; return the node reached, or -1 if the path breaks.
    static int Walk(string s) {
        int node = 0;
        foreach (char ch in s) {
            node = next[node, ch - 'a'];
            if (node == 0) return -1;
        }
        return node;
    }

    static string Yn(bool b) { return b ? "yes" : "no"; }

    static void Main() {
        string[] words = {"apple", "app", "bat"};
        foreach (string w in words) Insert(w);
        Console.WriteLine("words: " + string.Join(", ", words));
        int n;
        n = Walk("app"); Console.WriteLine("search(app): " + Yn(n != -1 && isEnd[n]));
        n = Walk("ap");  Console.WriteLine("search(ap): " + Yn(n != -1 && isEnd[n]));   // a prefix, not a word
        Console.WriteLine("startsWith(ap): " + Yn(Walk("ap") != -1));
        Console.WriteLine("startsWith(bo): " + Yn(Walk("bo") != -1));
        Console.WriteLine("nodes used: " + size);
        // Time: O(L) per operation for a word of length L. Space: O(total letters * 26).
    }
}

