import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] nums = {3, 10, 5, 25, 2, 8};
        System.out.println("nums: " + Arrays.toString(nums));

        int[][] child = new int[nums.length * 31 + 1][2];   // flat trie: child[node][bit], 0 = missing
        int size = 1;
        for (int x : nums) {                                // insert each number as 31 bits, high to low
            int node = 0;
            for (int b = 30; b >= 0; b--) {
                int bit = (x >> b) & 1;
                if (child[node][bit] == 0) child[node][bit] = size++;
                node = child[node][bit];
            }
        }

        int best = 0;
        for (int x : nums) {
            int node = 0, cur = 0;
            for (int b = 30; b >= 0; b--) {
                int bit = (x >> b) & 1;
                if (child[node][bit ^ 1] != 0) {            // opposite bit exists: this XOR bit becomes 1
                    cur |= 1 << b;
                    node = child[node][bit ^ 1];
                } else {
                    node = child[node][bit];                // forced to take the same bit
                }
            }
            best = Math.max(best, cur);
        }
        System.out.println("max xor (trie): " + best);

        int brute = 0;                                      // O(N^2) check of every pair
        for (int a : nums) for (int b : nums) brute = Math.max(brute, a ^ b);
        System.out.println("max xor (all pairs): " + brute);
        // Trie: O(31 * N) time and O(31 * N) nodes. All pairs: O(N^2) time.
    }
}

