import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 5;
        int[][] edges = {{0, 1, 4}, {0, 2, 1}, {2, 1, 2}, {1, 3, 1}, {2, 3, 5}, {3, 4, 3}};   // {from, to, weight}
        System.out.println("edges (from>to:weight): 0>1:4 0>2:1 2>1:2 1>3:1 2>3:5 3>4:3");
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) adj.get(e[0]).add(new int[]{e[1], e[2]});

        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[0] = 0;
        // Heap of {distance, node}: the closest unfinished node comes out first.
        PriorityQueue<int[]> pq = new PriorityQueue<>(
            (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        pq.add(new int[]{0, 0});
        int stale = 0;
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (d > dist[u]) { stale++; continue; }      // lazy deletion: an old, worse entry for u
            for (int[] e : adj.get(u)) {
                int v = e[0], nd = d + e[1];
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.add(new int[]{nd, v});            // no decrease-key: just push a better entry
                }
            }
        }
        System.out.println("shortest distances from 0: " + Arrays.toString(dist));
        System.out.println("stale heap entries skipped: " + stale);
        // Time: O(E log E) = O(E log V). Space: O(V + E).
    }
}

