using System;
using System.Collections.Generic;

class Program {
    // Tiny binary min-heap of int[] keys, compared left to right.
    static bool Less(int[] a, int[] b) {
        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return a[i] < b[i];
        return false;
    }
    static void Push(List<int[]> h, int[] x) {
        h.Add(x);
        int i = h.Count - 1;
        while (i > 0 && Less(h[i], h[(i - 1) / 2])) {
            int p = (i - 1) / 2;
            int[] t = h[i]; h[i] = h[p]; h[p] = t;
            i = p;
        }
    }
    static int[] Pop(List<int[]> h) {
        int[] top = h[0];
        h[0] = h[h.Count - 1];
        h.RemoveAt(h.Count - 1);
        int i = 0;
        while (true) {
            int m = i, l = 2 * i + 1, r = l + 1;
            if (l < h.Count && Less(h[l], h[m])) m = l;
            if (r < h.Count && Less(h[r], h[m])) m = r;
            if (m == i) break;
            int[] t = h[i]; h[i] = h[m]; h[m] = t;
            i = m;
        }
        return top;
    }

    static void Main() {
        int n = 5;
        int[][] edges = { new[] {0, 1, 4}, new[] {0, 2, 1}, new[] {2, 1, 2}, new[] {1, 3, 1}, new[] {2, 3, 5}, new[] {3, 4, 3} };
        Console.WriteLine("edges (from>to:weight): 0>1:4 0>2:1 2>1:2 1>3:1 2>3:5 3>4:3");
        List<int[]>[] adj = new List<int[]>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<int[]>();
        foreach (int[] e in edges) adj[e[0]].Add(new int[] {e[1], e[2]});
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = int.MaxValue;
        dist[0] = 0;
        List<int[]> pq = new List<int[]>();              // heap of {distance, node}: closest node first
        Push(pq, new int[] {0, 0});
        int stale = 0;
        while (pq.Count > 0) {
            int[] cur = Pop(pq);
            int d = cur[0], u = cur[1];
            if (d > dist[u]) { stale++; continue; }      // lazy deletion: an old, worse entry for u
            foreach (int[] e in adj[u]) {
                int v = e[0], nd = d + e[1];
                // No decrease-key: just push a better entry.
                if (nd < dist[v]) { dist[v] = nd; Push(pq, new int[] {nd, v}); }
            }
        }
        Console.WriteLine("shortest distances from 0: [" + string.Join(", ", dist) + "]");
        Console.WriteLine("stale heap entries skipped: " + stale);
        // Time: O(E log E) = O(E log V). Space: O(V + E).
    }
}

