// Tiny binary heap: the item that is "less" than all others sits at h[0].
function push(h, x) {
  h.push(x);
  let i = h.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (!less(h[i], h[p])) break;
    [h[i], h[p]] = [h[p], h[i]];
    i = p;
  }
}
function pop(h) {
  const top = h[0], last = h.pop();
  if (h.length > 0) {
    h[0] = last;
    let i = 0;
    while (true) {
      let m = i;
      const l = 2 * i + 1, r = l + 1;
      if (l < h.length && less(h[l], h[m])) m = l;
      if (r < h.length && less(h[r], h[m])) m = r;
      if (m === i) break;
      [h[i], h[m]] = [h[m], h[i]];
      i = m;
    }
  }
  return top;
}
