using System;
using System.Collections.Generic;

class Program {
    // Tiny binary min-heap of int[] keys, compared left to right.
    static bool Less(int[] a, int[] b) {
        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return a[i] < b[i];
        return false;
    }
    static void Push(List<int[]> h, int[] x) {
        h.Add(x);
        int i = h.Count - 1;
        while (i > 0 && Less(h[i], h[(i - 1) / 2])) {
            int p = (i - 1) / 2;
            int[] t = h[i]; h[i] = h[p]; h[p] = t;
            i = p;
        }
    }
    static int[] Pop(List<int[]> h) {
        int[] top = h[0];
        h[0] = h[h.Count - 1];
        h.RemoveAt(h.Count - 1);
        int i = 0;
        while (true) {
            int m = i, l = 2 * i + 1, r = l + 1;
            if (l < h.Count && Less(h[l], h[m])) m = l;
            if (r < h.Count && Less(h[r], h[m])) m = r;
            if (m == i) break;
            int[] t = h[i]; h[i] = h[m]; h[m] = t;
            i = m;
        }
        return top;
    }

    static void Main() {
        string[] names = {"A", "B", "C", "D", "E"};
        int[] priority = {2, 1, 2, 1, 1};              // smaller number = more urgent
        string input = "";
        for (int i = 0; i < names.Length; i++) input += " " + names[i] + "(p" + priority[i] + ")";
        Console.WriteLine("submitted:" + input);

        // Entry = {priority, seq}. The seq tie-breaker makes equal priorities come out first-in, first-out.
        List<int[]> pq = new List<int[]>();
        int seq = 0;                                   // grows by one for every submitted task
        for (int i = 0; i < names.Length; i++) Push(pq, new int[] {priority[i], seq++});

        string output = "";
        while (pq.Count > 0) output += " " + names[Pop(pq)[1]];   // seq doubles as the task index here
        Console.WriteLine("run order:" + output);
        // Time: O(log N) per submit and per run. Space: O(N).
    }
}

