import java.util.*;

public class Main {
    static int[][] next = new int[64][26];
    static boolean[] isEnd = new boolean[64];
    static int size = 1;

    static void insert(String w) {
        int node = 0;
        for (char ch : w.toCharArray()) {
            int c = ch - 'a';
            if (next[node][c] == 0) next[node][c] = size++;
            node = next[node][c];
        }
        isEnd[node] = true;
    }

    public static void main(String[] args) {
        String[] vocab = {"un", "believ", "able", "a", "b", "e", "i", "l", "n", "u", "v"};
        for (String w : vocab) insert(w);
        String text = "unbelievable";
        System.out.println("vocab: " + String.join(", ", vocab));
        System.out.println("text: " + text);

        List<String> tokens = new ArrayList<>();
        int pos = 0;
        while (pos < text.length()) {
            int node = 0, bestEnd = -1;
            // Walk the trie as far as the text allows, remembering the last place a token ended.
            for (int j = pos; j < text.length(); j++) {
                node = next[node][text.charAt(j) - 'a'];
                if (node == 0) break;                  // no vocabulary piece continues this way
                if (isEnd[node]) bestEnd = j + 1;      // longest match so far
            }
            if (bestEnd == -1) bestEnd = pos + 1;      // unknown character: emit it alone
            tokens.add(text.substring(pos, bestEnd));
            pos = bestEnd;
        }
        System.out.println("tokens: " + String.join(" | ", tokens));
        // Time: O(N * M), N = text length, M = longest vocabulary piece. Space: O(total vocabulary letters).
    }
}

